mapper.update:
UPDATE admin_job
SET heartbeat_at = now(), updated_at = now()
WHERE id = #{jobId}
  AND status = 'RUNNING'
  AND attempt = #{attempt}
  AND lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM admin_job
    WHERE id = #{jobId}
      AND status = 'RUNNING'
      AND attempt = #{attempt}
      AND lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)
)
